import heapq


def cheapestRoute(n, roads, fees, src, dst):
    adj = [[] for _ in range(n)]
    for a, b, toll in roads:
        adj[a].append((b, toll + fees[b]))
        adj[b].append((a, toll + fees[a]))
    INF = float('inf')
    dist = [INF] * n
    dist[src] = fees[src]
    heap = [(fees[src], src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == dst:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1
